INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'What Music Do You Like?', 'People like different kinds of music. Some people prefer music that has great lyrics, because the words tell a story. Other people like music that they can dance to. They enjoy fast songs with a strong beat. Some like quiet, smooth music that helps them relax. Others love electronic music that is loud and exciting. There are also people who like singers that play their own instruments. Music is a part of our lives. It can make us happy when we are sad. No matter what kind of music you like, the best music is the music that touches your heart.', '说明文', 101, '[{"q": "What do some people prefer in music?", "answer": "C", "options": ["Silence.", "Loud noise.", "Music that has great lyrics.", "Music with no words."], "explanation": "原文:prefer music that has great lyrics"}, {"q": "Why do some people like music with lyrics?", "answer": "D", "options": ["It is fast.", "It is loud.", "It is cheap.", "The words tell a story."], "explanation": "原文:the words tell a story"}, {"q": "What kind of music helps people relax?", "answer": "C", "options": ["Fast music.", "Loud music.", "Quiet, smooth music.", "Electronic music."], "explanation": "原文:quiet, smooth music that helps them relax"}, {"q": "What do some people love about electronic music?", "answer": "B", "options": ["It is quiet.", "It is loud and exciting.", "It has no beat.", "It is slow."], "explanation": "原文:loud and exciting"}, {"q": "What is the best music according to the writer?", "answer": "A", "options": ["Music that touches your heart.", "Loud music.", "Fast music.", "Old music."], "explanation": "原文:touches your heart"}]'::jsonb, '[{"word": "prefer", "cn": "更喜欢"}, {"word": "lyrics", "cn": "歌词"}, {"word": "smooth", "cn": "悦耳的;平滑的"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'What Do You Feel Like Watching?', 'When I am tired, I prefer movies that can cheer me up. Comedies like Kung Fu Panda are funny. The characters may not be perfect, but they try their best to solve their problems. After I watch them, my problems suddenly seem less serious, and I feel much better again. I don''t often like dramas or documentaries when I am sad or tired. Dramas like Titanic make me feel even sadder. Documentaries like March of the Penguins are slow and quiet. But sometimes, when I am bored, I like to watch movies that are scary. They give me something to think about. Once in a while, scary movies are fun.', '说明文', 110, '[{"q": "What kind of movies does the writer prefer when tired?", "answer": "A", "options": ["Movies that can cheer him up.", "Scary movies.", "Slow movies.", "Sad movies."], "explanation": "原文:movies that can cheer me up"}, {"q": "Why does the writer like comedies?", "answer": "C", "options": ["They are sad.", "They are scary.", "The characters try their best.", "They are slow."], "explanation": "原文:try their best to solve their problems"}, {"q": "How does Titanic make the writer feel?", "answer": "D", "options": ["Calmer.", "Happier.", "Braver.", "Even sadder."], "explanation": "原文:make me feel even sadder"}, {"q": "When does the writer like scary movies?", "answer": "B", "options": ["When he is happy.", "When he is bored.", "When he is sad.", "When he is tired."], "explanation": "原文:when I am bored"}, {"q": "What do scary movies give the writer?", "answer": "C", "options": ["A happy ending.", "A quiet night.", "Something to think about.", "A good sleep."], "explanation": "原文:something to think about"}]'::jsonb, '[{"word": "prefer", "cn": "更喜欢"}, {"word": "comedies", "cn": "喜剧片"}, {"word": "serious", "cn": "严重的;严肃的"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Sad but Beautiful', 'Abing was a folk musician who was born in the city of Wuxi in 1893. His mother died when he was very young. Abing''s father taught him to play many musical instruments. Sadly, Abing later became ill and could not see. Life grew worse for Abing. He was very poor. Not only that, but he developed a serious illness. He had no home. But Abing did not give up. He kept playing music in the streets. In his lifetime, Abing wrote over 600 pieces of music. His most famous piece is Erquan Yingyue. It is a piece that reflects his hard life, but it is also full of hope. Today, Abing''s music is loved by people all over the world.', '记叙文', 120, '[{"q": "When was Abing born?", "answer": "A", "options": ["In 1893.", "In 1938.", "In 1983.", "In 1839."], "explanation": "原文:born...in 1893"}, {"q": "Who taught Abing to play instruments?", "answer": "A", "options": ["His father.", "His friend.", "His teacher.", "His mother."], "explanation": "原文:father taught him"}, {"q": "What happened to Abing later?", "answer": "A", "options": ["He became ill and could not see.", "He moved away.", "He stopped music.", "He became rich."], "explanation": "原文:became ill and could not see"}, {"q": "How many pieces of music did Abing write?", "answer": "B", "options": ["Over 6000.", "Over 600.", "Over 6.", "Over 60."], "explanation": "原文:over 600 pieces"}, {"q": "What does Erquan Yingyue reflect?", "answer": "D", "options": ["His rich life.", "His travels.", "His happy childhood.", "His hard life."], "explanation": "原文:reflects his hard life"}]'::jsonb, '[{"word": "musician", "cn": "音乐家"}, {"word": "instruments", "cn": "乐器"}, {"word": "lifetime", "cn": "一生"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Why We Love Music', 'Why do people all over the world love music? One reason is that music can express our feelings. When we are happy, we sing happy songs. When we feel down, sad music helps us. Music can also bring people together. At a concert, thousands of people who don''t know each other share the same joy. Music has no language. A person who speaks Chinese and a person who speaks English can enjoy the same song. Music can even help us remember things. A song that we heard long ago can bring back old memories. Music is truly a gift that everyone can enjoy.', '议论文', 103, '[{"q": "What is one reason people love music?", "answer": "A", "options": ["It can express our feelings.", "It is free.", "It is fast.", "It is loud."], "explanation": "原文:music can express our feelings"}, {"q": "What do we do when we are happy?", "answer": "C", "options": ["Stay quiet.", "Sing sad songs.", "Sing happy songs.", "Stop singing."], "explanation": "原文:When we are happy, we sing happy songs"}, {"q": "What can music do at a concert?", "answer": "A", "options": ["Bring people together.", "Send people home.", "Stop the noise.", "Make people sad."], "explanation": "原文:bring people together"}, {"q": "Can people who speak different languages enjoy the same song?", "answer": "C", "options": ["Only with words.", "No.", "Yes.", "Only sometimes."], "explanation": "原文:Music has no language"}, {"q": "What can a song from long ago bring back?", "answer": "B", "options": ["New friends.", "Old memories.", "Money.", "Energy."], "explanation": "原文:bring back old memories"}]'::jsonb, '[{"word": "express", "cn": "表达"}, {"word": "feelings", "cn": "情感"}, {"word": "memories", "cn": "回忆"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Different Kinds of Movies', 'There are many kinds of movies, and people enjoy different ones. Comedies are movies that make us laugh. They are great when we want to relax. Action movies are movies that are full of exciting scenes. They often have superheroes who save the world. Documentaries are movies that teach us about real life, like nature or history. Some people find them a little slow, but others love to learn from them. Dramas are movies that show strong feelings. They may make us cry. Scary movies are movies that frighten us. Some people love them, while others can''t watch them at all. Which kind of movie do you prefer?', '说明文', 108, '[{"q": "What are comedies?", "answer": "B", "options": ["Movies that scare us.", "Movies that make us laugh.", "Movies that teach us.", "Movies that make us cry."], "explanation": "原文:comedies...make us laugh"}, {"q": "What do action movies often have?", "answer": "B", "options": ["Slow scenes.", "Superheroes who save the world.", "Real history.", "Sad endings."], "explanation": "原文:superheroes who save the world"}, {"q": "What do documentaries teach us about?", "answer": "A", "options": ["Real life, like nature or history.", "Made-up heroes.", "Music.", "Funny stories."], "explanation": "原文:teach us about real life"}, {"q": "What may dramas make us do?", "answer": "D", "options": ["Dance.", "Laugh.", "Sleep.", "Cry."], "explanation": "原文:may make us cry"}, {"q": "What do scary movies do?", "answer": "C", "options": ["Relax us.", "Make us laugh.", "Frighten us.", "Teach us."], "explanation": "原文:scary movies...frighten us"}]'::jsonb, '[{"word": "comedies", "cn": "喜剧片"}, {"word": "superheroes", "cn": "超级英雄"}, {"word": "frighten", "cn": "使害怕"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'School Music Club Notice', 'JOIN THE SCHOOL MUSIC CLUB! Do you love music? Come and join us! WHO CAN JOIN: Any student who enjoys music is welcome. You don''t need to be a master. WHAT WE DO: We listen to music that comes from around the world. We also learn to play instruments that are easy for beginners, like the guitar. SPECIAL EVENT: This month, we will watch a documentary that tells the story of Abing, a famous Chinese musician. WHEN: Every Friday, 4:00 p.m. to 5:30 p.m. WHERE: Music Room 203. Come and meet friends who share your love of music. Music is a gift that everyone can enjoy!', '应用文', 106, '[{"q": "Who can join the music club?", "answer": "C", "options": ["Only singers.", "Only teachers.", "Any student who enjoys music.", "Only masters."], "explanation": "原文:Any student who enjoys music"}, {"q": "What instruments do they learn?", "answer": "D", "options": ["Hard instruments.", "Only the piano.", "No instruments.", "Instruments easy for beginners, like the guitar."], "explanation": "原文:easy for beginners, like the guitar"}, {"q": "What is the special event this month?", "answer": "D", "options": ["A test.", "A concert.", "A dance.", "A documentary about Abing."], "explanation": "原文:documentary that tells the story of Abing"}, {"q": "When does the club meet?", "answer": "D", "options": ["Every Monday.", "On weekends.", "Every day.", "Every Friday."], "explanation": "原文:Every Friday"}, {"q": "Where does the club meet?", "answer": "B", "options": ["The gym.", "Music Room 203.", "Room 105.", "The library."], "explanation": "原文:Music Room 203"}]'::jsonb, '[{"word": "master", "cn": "大师;能手"}, {"word": "documentary", "cn": "纪录片"}, {"word": "instrument", "cn": "乐器;器械"}]'::jsonb, 3, '9', 'U9');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'The Music I Love', 'I love music more than anything. I prefer music (1)____ I can sing along with. When I feel (2)____, a happy song can cheer me up. My favorite (3)____ are pop and rock. I like songs that have great (4)____, because the words tell a story. My friend Lisa likes (5)____ music that helps her relax. My brother prefers (6)____ music that is loud and fast. We all like (7)____ kinds of music, but that''s okay. Music is a (8)____ that everyone can enjoy. No matter what kind you like, the best music is the music that (9)____ your heart. That''s why I will always (10)____ music.', 107, 3, '[{"q": "1", "answer": "A", "options": ["that", "where", "whose", "who"], "explanation": "[定从] music是物→that"}, {"q": "2", "answer": "A", "options": ["down", "glad", "happy", "up"], "explanation": "沮丧 feel down"}, {"q": "3", "answer": "A", "options": ["kinds", "game", "color", "price"], "explanation": "种类 kinds"}, {"q": "4", "answer": "C", "options": ["game", "price", "lyrics", "color"], "explanation": "歌词 lyrics"}, {"q": "5", "answer": "D", "options": ["loud", "fast", "sour", "smooth"], "explanation": "悦耳 smooth"}, {"q": "6", "answer": "B", "options": ["soft", "electronic", "slow", "quiet"], "explanation": "电子 electronic"}, {"q": "7", "answer": "B", "options": ["quiet", "different", "empty", "same"], "explanation": "不同 different"}, {"q": "8", "answer": "C", "options": ["game", "color", "gift", "price"], "explanation": "礼物 gift"}, {"q": "9", "answer": "B", "options": ["breaks", "touches", "loses", "throws"], "explanation": "触动 touches"}, {"q": "10", "answer": "D", "options": ["leave", "lose", "hate", "love"], "explanation": "爱 love"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'My Favorite Movies', 'I love watching movies in my (1)____ time. I prefer movies (2)____ make me laugh. Comedies are my favorite (3)____. When I am tired, a funny movie can (4)____ me up. I don''t like movies that are too (5)____, because they make me feel down. My sister likes (6)____ that teach her about real life, like nature films. My father prefers (7)____ movies with superheroes who save the world. Once in a (8)____, I watch a scary movie, but only with friends. After a movie, I always feel more (9)____. Watching movies is a great way to (10)____ after a busy week.', 102, 3, '[{"q": "1", "answer": "B", "options": ["work", "spare", "study", "busy"], "explanation": "空闲 spare time"}, {"q": "2", "answer": "D", "options": ["where", "who", "whose", "that"], "explanation": "[定从] movies是物→that"}, {"q": "3", "answer": "A", "options": ["kind", "price", "color", "game"], "explanation": "种类 kind"}, {"q": "4", "answer": "B", "options": ["lose", "cheer", "break", "throw"], "explanation": "使振奋 cheer up"}, {"q": "5", "answer": "D", "options": ["funny", "glad", "happy", "sad"], "explanation": "悲伤 sad"}, {"q": "6", "answer": "B", "options": ["prices", "documentaries", "games", "colors"], "explanation": "纪录片 documentaries"}, {"q": "7", "answer": "A", "options": ["action", "soft", "quiet", "slow"], "explanation": "动作 action movies"}, {"q": "8", "answer": "C", "options": ["color", "time", "while", "price"], "explanation": "偶尔 once in a while"}, {"q": "9", "answer": "A", "options": ["relaxed", "sad", "tired", "busy"], "explanation": "放松 relaxed"}, {"q": "10", "answer": "C", "options": ["study", "cry", "relax", "work"], "explanation": "放松 relax"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'Abing''s Story', 'Abing was a folk musician (1)____ was born in Wuxi. When he was young, his mother (2)____. His father taught him to play many musical (3)____. Sadly, Abing later became (4)____ and could not see. His life grew very (5)____. He was poor and had no home. But Abing never gave (6)____. He kept playing music in the (7)____. In his lifetime, he wrote over 600 (8)____ of music. His most famous piece (9)____ his hard life but is full of hope. Today, his music is (10)____ by people all over the world. Abing''s story is sad but beautiful.', 99, 3, '[{"q": "1", "answer": "A", "options": ["who", "where", "which", "whose"], "explanation": "[定从] musician是人→who"}, {"q": "2", "answer": "B", "options": ["lived", "died", "ran", "sang"], "explanation": "去世 died"}, {"q": "3", "answer": "B", "options": ["prices", "instruments", "games", "colors"], "explanation": "乐器 instruments"}, {"q": "4", "answer": "D", "options": ["strong", "happy", "rich", "ill"], "explanation": "生病 ill"}, {"q": "5", "answer": "B", "options": ["rich", "hard", "easy", "good"], "explanation": "艰难 hard"}, {"q": "6", "answer": "C", "options": ["off", "on", "up", "in"], "explanation": "放弃 give up"}, {"q": "7", "answer": "A", "options": ["streets", "color", "game", "price"], "explanation": "街头 streets"}, {"q": "8", "answer": "D", "options": ["prices", "games", "colors", "pieces"], "explanation": "首 pieces of music"}, {"q": "9", "answer": "A", "options": ["reflects", "loses", "breaks", "throws"], "explanation": "反映 reflects"}, {"q": "10", "answer": "C", "options": ["hated", "lost", "loved", "sold"], "explanation": "被喜爱 loved"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'A Concert Night', 'Last weekend, I went to a concert with my (1)____. The singer was an artist (2)____ writes her own songs. The music hall was full of people (3)____ love music. When the music started, everyone felt (4)____. The singer''s voice was (5)____ and beautiful. She sang songs that had great (6)____. Some songs were happy, and some were (7)____. One song was so (8)____ that many people cried. Music can (9)____ our feelings in a special way. After the concert, I felt (10)____ and happy. It was a night I will never forget. I hope to go to another concert soon.', 101, 3, '[{"q": "1", "answer": "B", "options": ["color", "friends", "game", "price"], "explanation": "朋友 friends"}, {"q": "2", "answer": "B", "options": ["whose", "who", "where", "which"], "explanation": "[定从] artist是人→who"}, {"q": "3", "answer": "D", "options": ["which", "where", "whose", "who"], "explanation": "[定从] people是人→who"}, {"q": "4", "answer": "D", "options": ["tired", "sad", "bored", "excited"], "explanation": "兴奋 excited"}, {"q": "5", "answer": "C", "options": ["sour", "fast", "smooth", "loud"], "explanation": "悦耳 smooth"}, {"q": "6", "answer": "A", "options": ["lyrics", "prices", "games", "colors"], "explanation": "歌词 lyrics"}, {"q": "7", "answer": "A", "options": ["sad", "funny", "fast", "quiet"], "explanation": "悲伤 sad"}, {"q": "8", "answer": "B", "options": ["boring", "moving", "cheap", "easy"], "explanation": "动人 moving"}, {"q": "9", "answer": "A", "options": ["express", "lose", "throw", "break"], "explanation": "表达 express"}, {"q": "10", "answer": "C", "options": ["busy", "tired", "relaxed", "angry"], "explanation": "放松 relaxed"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'Kinds of Movies', 'There are many kinds of movies (1)____ people enjoy. Comedies are movies that make us (2)____. They are great when we want to (3)____. Action movies are full of exciting (4)____. They often have superheroes (5)____ save the world. Documentaries are movies that (6)____ us about real life. Some people find them (7)____, but others love them. Dramas are movies that show strong (8)____. They may make us cry. Scary movies (9)____ us, and not everyone likes them. There is a kind of movie for everyone. Which kind do you (10)____?', 91, 3, '[{"q": "1", "answer": "D", "options": ["who", "where", "whose", "that"], "explanation": "[定从] movies是物→that"}, {"q": "2", "answer": "A", "options": ["laugh", "sleep", "run", "cry"], "explanation": "笑 laugh"}, {"q": "3", "answer": "C", "options": ["fight", "study", "relax", "work"], "explanation": "放松 relax"}, {"q": "4", "answer": "B", "options": ["colors", "scenes", "prices", "games"], "explanation": "场面 scenes"}, {"q": "5", "answer": "A", "options": ["who", "which", "where", "whose"], "explanation": "[定从] superheroes是人→who"}, {"q": "6", "answer": "A", "options": ["teach", "lose", "throw", "break"], "explanation": "教 teach"}, {"q": "7", "answer": "B", "options": ["loud", "slow", "fast", "sweet"], "explanation": "慢 slow"}, {"q": "8", "answer": "D", "options": ["colors", "games", "prices", "feelings"], "explanation": "情感 feelings"}, {"q": "9", "answer": "B", "options": ["help", "frighten", "teach", "save"], "explanation": "使害怕 frighten"}, {"q": "10", "answer": "C", "options": ["lose", "break", "prefer", "throw"], "explanation": "更喜欢 prefer"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U9', 'Music Brings Us Together', 'Music is something (1)____ everyone in the world can enjoy. It has no (2)____. A person who speaks Chinese and a person (3)____ speaks English can love the same song. Music can (4)____ our feelings. When we are happy, we sing happy (5)____. When we feel down, sad music (6)____ us. Music can also bring people (7)____. At a concert, thousands of strangers share the same (8)____. A song that we heard long ago can bring back old (9)____. Music is truly a (10)____ that everyone can enjoy. That is why music is loved all over the world.', 98, 3, '[{"q": "1", "answer": "B", "options": ["who", "that", "whose", "where"], "explanation": "[定从] something是物→that"}, {"q": "2", "answer": "D", "options": ["color", "price", "game", "language"], "explanation": "语言 language"}, {"q": "3", "answer": "C", "options": ["where", "which", "who", "whose"], "explanation": "[定从] person是人→who"}, {"q": "4", "answer": "B", "options": ["break", "express", "lose", "throw"], "explanation": "表达 express"}, {"q": "5", "answer": "C", "options": ["colors", "prices", "songs", "games"], "explanation": "歌 songs"}, {"q": "6", "answer": "B", "options": ["throws", "helps", "breaks", "loses"], "explanation": "帮助 helps"}, {"q": "7", "answer": "A", "options": ["together", "apart", "away", "alone"], "explanation": "一起 together"}, {"q": "8", "answer": "A", "options": ["joy", "game", "price", "color"], "explanation": "喜悦 joy"}, {"q": "9", "answer": "D", "options": ["colors", "prices", "games", "memories"], "explanation": "回忆 memories"}, {"q": "10", "answer": "A", "options": ["gift", "game", "color", "price"], "explanation": "礼物 gift"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·对话 What Music Do You Like', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'W: What kind of music do you like?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·短文 Abing''s Story', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'Abing was a folk musician who was born in Wuxi.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·对话 Choosing a Movie', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'W: Do you want to watch a movie tonight?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·短文 Why We Love Music', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'People all over the world love music.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·对话 At the Music Club', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'W: I want to join the music club. Can anyone join?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U9 听力·短文 Kinds of Movies', '九年级 Unit9 听力·音乐与电影/定语从句', 2, 'There are many kinds of movies for people to enjoy.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'The Music (or Movies) I Like', '用定语从句(that/which/who)介绍你喜欢的音乐或电影。写清你喜欢哪种、为什么喜欢、它给你什么感受。60词左右。', 'Write a short passage on the topic: "The Music (or Movies) I Like".', '["你喜欢哪种音乐/电影(用定语从句:music/movies that...)", "为什么喜欢", "你喜欢的歌手/导演(用who:singers who...)", "它给你的感受"]'::jsonb, 70, 100, 'I love music that I can sing along with. I prefer pop songs that have great lyrics, because the words tell a story. My favorite singer is a musician who writes her own songs. When I feel down, music that is happy can cheer me up. When I am tired, smooth music that is quiet helps me relax. Music is a gift that touches my heart, and that is why I love it so much.', 'content:含喜欢的类型/原因/歌手/感受(4分)；language:正确使用定语从句that/which/who(3分)；structure:语句通顺、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'The Music (or Movies) I Like', '["I like music/movies that ...", "I prefer ... that ...", "singers/people who ...", "music that I can dance to", "movies that make me laugh", "It makes me feel ..."]'::jsonb, '[]'::jsonb, '要点:你喜欢哪种音乐/电影(用定语从句:music/movies that...)；为什么喜欢；你喜欢的歌手/导演(用who:singers who...)；它给你的感受', '9', 'U9' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U9' AND topic='The Music (or Movies) I Like');
